## 7️⃣ 購物車頁面

```tsx
// src/pages/CartPage.tsx
import { useCartStore } from '../store/cartStore';
import { Link } from 'react-router-dom';

export default function CartPage() {
  const { items, removeItem, updateQuantity, clearCart } = useCartStore();

  const total = items.reduce((sum, i) => sum + i.price * i.quantity, 0);

  return (
    <div className="p-4 max-w-4xl mx-auto">
      <h2 className="text-2xl font-bold mb-4">購物車</h2>
      {items.length === 0 ? (
        <p>您的購物車是空的。</p>
      ) : (
        <>
          <ul className="space-y-4">
            {items.map((i) => (
              <li key={i.id} className="flex items-center space-x-4">
                <img src={i.imageUrl} alt={i.name} className="w-16 h-16 object-cover rounded" />
                <div className="flex-1">
                  <h3 className="font-medium">{i.name}</h3>
                  <p>${i.price.toFixed(2)} × {i.quantity}</p>
                </div>
                <input
                  type="number"
                  min="1"
                  value={i.quantity}
                  onChange={(e) => updateQuantity(i.id, Number(e.target.value))}
                  className="w-16 border rounded px-2 py-1"
                />
                <button onClick={() => removeItem(i.id)} className="text-red-600 hover:text-red-800">
                  刪除
                </button>
              </li>
            ))}
          </ul>

          <div className="mt-6 flex justify-between items-center">
            <span className="text-xl font-bold">總計: ${total.toFixed(2)}</span>
            <div>
              <button onClick={clearCart} className="mr-4 text-gray-600 hover:text-gray-800">
                清空購物車
              </button>
              <Link to="/checkout" className="bg-blue-600 text-white px-6 py-2 rounded hover:bg-blue-700">
                前往結帳
              </Link>
            </div>
          </div>
        </>
      )}
    </div>
  );
}
```

